// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency) public {
        // Ensure sender is the DAO (which is address(this) in setup) or a governed address
        // to allow assertGovernanceApproved to proceed past the flashEnabled modifier
        vm.assume(sender == address(this) || sender != address(0));

        // Optionally set governed status for non-DAO callers
        address[] memory governables = new address[](1);
        bool[] memory isGoverned = new bool[](1);
        governables[0] = sender;
        isGoverned[0] = true;

        // Use prank to simulate the successful proposal context for setGoverned
        // Since we need setGoverned to be callable, we need to call it from a successful proposal
        // In test setup, the DAO is address(this), so we can call assertSuccessfulProposal-compatible functions
        // For simplicity, we assume the DAO can call setGoverned directly if configured is false
        // But to be safe, we'll just use a governed address that is already the DAO itself

        // Actually, the simplest approach: call assertGovernanceApproved directly from DAO
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency));

        // After the call, check that DAO is not zero
        assertTrue(c.DAO() != address(0), "DAO should never be zero");
    }
}

